// NB-04 · spec: .qa/e2e/specs/nearby.md 1.4 · две роли · меняет данные → в finally оба false.
import { test, expect } from '../../fixtures';
import { openRole, turnOff, meetPair, reloadLists, card, NAME, listTitle } from './nearby-helpers';

test.use({ browserName: 'webkit' });

test.describe('היו כאן — משתמשים שהיו בקרבת מקום', () => {
  test.describe.configure({ timeout: 180_000 });
  test('двое рядом с согласием — список 17.01a: счётчик, карточка, сердце, «פעם אחת · HH:MM»; видят друг друга @iphone @data (#ab0123 #67c751 #ee51bb)', async ({ browser }) => {
    const reg1 = await openRole(browser, 'reg1');
    const reg2 = await openRole(browser, 'reg2');
    try {
      await meetPair(reg1, reg2);
      const p = reg1.page;
      await expect(p.getByText('אדם אחד היה לידך')).toBeVisible();
      await expect(p.getByText('ב-7 השעות האחרונות')).toBeVisible();
      await expect(listTitle(p)).toBeVisible();
      await expect(p.getByText('מהחדש לישן')).toBeVisible();
      const c = card(p, NAME.reg2);
      await expect(c.getByRole('button', { name: 'אהבתי' })).toBeVisible();
      await expect(c.getByText(/^פעם אחת · \d{2}:\d{2}$/)).toBeVisible();

      const { recent } = await reloadLists(p);
      const row = recent.find((r) => String(r.id) === reg2.id);
      expect(row, 'reg2 в nearby_recent у reg1').toBeTruthy();
      expect(Number(row!.min_distance_m)).toBeLessThanOrEqual(250);
      expect(row).not.toHaveProperty('lat');
      expect(row).not.toHaveProperty('lng');

      // Взаимно: reg2 после перезагрузки видит reg1.
      await reloadLists(reg2.page);
      await expect(card(reg2.page, NAME.reg1)).toBeVisible();
    } finally {
      await turnOff(reg1);
      await turnOff(reg2);
      await reg1.ctx.close();
      await reg2.ctx.close();
    }
  });
});
